-- PublicEcho Large Seed File 3: Users (Citizens, Officials, Admins) and Official Profiles
USE railway;

-- Citizens (IDs 100 to 599)
ON DUPLICATE KEY UPDATE `name` = VALUES(`name`), `email` = VALUES(`email`), `password_hash` = VALUES(`password_hash`), `phone` = VALUES(`phone`), `role_id` = VALUES(`role_id`);

-- Officials Profiles
ON DUPLICATE KEY UPDATE `user_id` = VALUES(`user_id`), `department_id` = VALUES(`department_id`), `ward_id` = VALUES(`ward_id`), `designation` = VALUES(`designation`), `office_address` = VALUES(`office_address`), `status` = VALUES(`status`);
